#!/usr/bin/env python3
"""Audit delivered holdings and document every decision in both fixed cohorts."""
import collections,importlib.util,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
s=importlib.util.spec_from_file_location('delivery',ROOT/'ops/apply-random-5000-round3-20261007.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m);r=m.r;RUN=m.RUN;d=m.d
def cell(v):return str(v or '').replace('|','\\|').replace('\n',' ')
def main():
 sample=r.load(RUN/'sample.json');rows=r.load(RUN/'baseline.json.gz');assert r.sha((RUN/'baseline.json.gz').read_bytes())==sample['baseline_sha256'];newids=sample['artwork_ids'];oldids=sample['followup_lead_ids'];assert len(newids)==5000 and len(oldids)==489 and not(set(newids)&set(oldids))
 original=r.load(m.OLD/'sample.json');previous=r.load(m.t.t.PREV/'sample.json');assert not(set(newids)&set(original['artwork_ids']+previous['artwork_ids']))
 applied={};applied_wave={};verifications=[];deliveryholds=[];newinstitutions={}
 for folder in sorted((RUN/'delivery').iterdir()):
  plan=r.load(folder/'plan.json.gz');deliveryholds+=plan['held']
  if not(folder/'verification.json').exists():
   assert not list((folder/'production').glob('*.json')),'Unverified committed batches require audit before reporting';continue
  verification=r.load(folder/'verification.json');assert not verification['errors'];verifications.append(verification)
  for c in plan['claims']:assert c['artwork_id']not in applied;applied[c['artwork_id']]=c;applied_wave[c['artwork_id']]=plan['wave']
  for i in r.load(folder/'plan-pin.json')['new_institutions']:newinstitutions[i['id']]=i
 assert applied
 live={}
 with r.connect('production')as db:
  for offset in range(0,len(rows),500):
   live.update(d.snapshots(db,list(rows)[offset:offset+500]));print('Final audit',min(offset+500,len(rows)),'/',len(rows),flush=True)
  institutions={str(x['id']):x['name']for x in db.execute('SELECT id,name FROM institutions')}
  task_assertions=db.execute("SELECT count(*) n FROM artwork_location_assertions WHERE id=ANY(%s::uuid[])",([d.uid(applied_wave[aid]+'/holding/'+aid)for aid in applied],)).fetchone()['n']
 assert task_assertions==len(applied)
 for aid,c in applied.items():assert live[aid]['artwork']['current_institution_id']==c['institution']['id']
 wd=r.load(RUN/'wikidata-assessment-v4.json.gz');wdby={x['artwork_id']:x for x in wd['outcomes']};wiki=r.load(RUN/'wikiart-holding-plan-v9.json.gz');wikiby={x['artwork_id']:x for x in wiki['outcomes']};native=r.load(RUN/'native-identity-preflight.json.gz');combined=r.load(RUN/'primary-plans/combined-80-reviewed.json.gz');held=collections.defaultdict(list)
 for h in [*native['held'],*deliveryholds,*combined['holds']]:held[h['artwork_id']].append(h)
 webpins=[];webleads=collections.defaultdict(list)
 for folder in [m.OLD,m.t.t.PREV,RUN]:
  pin=r.load(folder/'latest-web-review.json');web=r.load(folder/pin['path']);webpins.append({'folder':str(folder.relative_to(ROOT)),**pin})
  for aid,leads in web['related_source_leads'].items():
   if aid in rows:webleads[aid]+=[{'source_url':x['source_url'],'source_title':x['source_title'],'possible_institutions':x['possible_institutions'],'outcome':x['outcome']}for x in leads]
 queried={q['artwork_id']for p in(RUN/'web-discovery').glob('*.json')for q in r.load(p)['queries']};assert len(queried)==4694 and queried<=set(newids+oldids);initial=r.load(RUN/'initial-source-review.json');assert set(newids)<=queried|set(initial['new_sample_exact_source_ids'])
 ledgers={};concurrent=[]
 for name,ids in [('new-5000',newids),('prior-489-leads',oldids)]:
  ledger=[]
  for aid in ids:
   a=rows[aid]['artwork'];current=live[aid]['artwork'];wc=wikiby[aid];dc=wdby[aid];notes=[];sources=[];museum=None;confidence=None;sourceplan=None
   if aid in applied:
    c=applied[aid];outcome='museum_assigned';museum=c['institution']['name'];confidence=c['editorial_confidence'];sources=[c['source_url']];notes=[c['identity_basis'],c['limitation']];sourceplan='delivery/'+applied_wave[aid]+'/plan.json.gz'
   elif current['current_institution_id']and any(h['claim_type']=='holding'and h['review_state']=='accepted'and not h['superseded_by']for h in live[aid]['assertions']):
    outcome='museum_already_assigned_since_previous_pass'if a['current_institution_id']else 'museum_assigned_by_concurrent_catalogue_work';museum=institutions.get(current['current_institution_id'],current['current_institution_id']);sources=[h['source_url']for h in live[aid]['assertions']if h['claim_type']=='holding'and h['review_state']=='accepted'and not h['superseded_by']];notes=['Observed production assignment by another catalogue operation; not counted as this pass’s write.'];concurrent.extend([aid]if not a['current_institution_id']else [])
   elif aid=='ee38aafe-c82a-535d-a8ae-8ffa1aa44558':
    outcome='identified_non_museum_collection';notes=['Official National Library of Wales record resolves the mixed WikiArt collection label.'];sources=['https://www.library.wales/discover-learn/digital-exhibitions/pictures/europeana-280/james-ward-an-overshot-mill-in-wales']
   elif aid in held:
    outcome='duplicate_or_changed_catalogue_record';notes=[h['reason']for h in held[aid]]
   elif dc['collection_candidates']and all(x.get('hold')=='documented_non_museum_collection'for x in dc['collection_candidates']):outcome='identified_non_museum_collection';notes=['Collection source identifies a library, public agency, private collection or another non-museum body.']
   elif wc['outcome']=='documented_non_museum_private_foundation':outcome='identified_non_museum_collection';notes=wc['source_locations']
   elif wc['outcome']=='private_collection_or_unknown_or_destroyed':outcome='source_reports_private_unknown_or_destroyed';notes=wc['source_locations']
   elif wc['outcome']=='documented_non_museum_site_or_collection_requires_separate_site_review':outcome='identified_non_museum_site';notes=wc['source_locations']
   elif dc['outcome']in ['version_identity_insufficient','no_single_current_collection','qualified_collection_statement']or wc['outcome']in ['specific_print_impression_requires_inventory_or_version_evidence','replica_or_maquette_version_not_resolved','multiple_museums_in_literal_source_label']:outcome='object_version_or_collection_evidence_below_80';notes=[dc['outcome'],wc['outcome']]
   elif dc['collection_candidates']or webleads.get(aid)or wc['source_locations']:outcome='collection_lead_below_80_after_review';notes=[dc['outcome'],wc['outcome']]
   else:outcome='no_museum_identified_after_research';notes=[dc['outcome'],wc['outcome']]
   ledger.append({'artwork_id':aid,'title':a['title'],'creator':'; '.join(x['name']for x in rows[aid]['creator_keys'])or a.get('unlinked_creator_label'),'outcome':outcome,'museum':museum,'editorial_confidence':confidence,'calibrated_probability':False,'source_urls':sources or wc['source_urls'],'notes':notes,'source_plan':sourceplan,'wikidata_review':dc,'wikiart_review':wc,'additional_indexed_leads':webleads.get(aid,[]),'individual_followup_query_completed':aid in queried,'original_publication_status':a['status'],'current_publication_status':current['status']})
  ledgers[name]=ledger;r.save_gz(RUN/(name+'-results.json.gz'),ledger)
  lines=['# '+('Fresh random 5,000 artworks'if name=='new-5000'else 'Reassessment of 489 unresolved original leads'),'','Every decision below was made under the user-approved 80% editorial threshold. Museum connections do not establish ownership or current display.','','| Artwork | Creator | Decision | Museum | Confidence | Evidence |','|---|---|---|---|---|---|']
  for x in ledger:lines.append('| '+cell(x['title'])+' ('+x['artwork_id']+') | '+cell(x['creator'])+' | '+x['outcome']+' | '+cell(x['museum'])+' | '+(str(round(x['editorial_confidence']*100))+'%'if x['editorial_confidence']else '')+' | '+('<br>'.join('[source]('+u+')'for u in x['source_urls'][:3]))+' |')
  (RUN/(name+'-results.md')).write_text('\n'.join(lines)+'\n')
 counts={name:dict(collections.Counter(x['outcome']for x in ledger))for name,ledger in ledgers.items()};audit={'at':r.now(),'target':'production','new_random_sample':5000,'earlier_leads_reassessed':489,'new_sample_disjoint_from_previous_10000':True,'museum_assignments_applied':len(applied),'applied_new_sample':counts['new-5000'].get('museum_assigned',0),'applied_previous_leads':counts['prior-489-leads'].get('museum_assigned',0),'concurrent_assignments_observed':len(concurrent),'already_assigned_before_followup':sum(bool(rows[aid]['artwork']['current_institution_id'])for aid in oldids),'new_review_institutions':len(newinstitutions),'distinct_assigned_museums':len({c['institution']['id']for c in applied.values()}),'outcomes':counts,'all_new_sample_artworks_researched':5000,'individual_followup_queries':len(queried),'exact_source_review_without_additional_search':len(initial['new_sample_exact_source_ids']),'source_supported_matches_before_duplicate_and_concurrency_checks':len(combined['claims']),'source_class_counts':dict(collections.Counter(c['origin_provider']for c in applied.values())),'offline_regression_tests_passed':21,'verification_receipts':verifications,'source_policy':'WikiArt approved. Museum matching minimum 80% editorial confidence; uncalibrated assessment, not a measured probability.','publication_and_date_fields_preserved':True,'creator_labels_relationships_and_images_preserved':True,'local_database_writes':0,'new_artwork_records':0,'image_downloads_or_changes':0,'new_display_claims':0,'backup':r.load(RUN/'backups.json')['production'],'errors':[]};r.save(RUN/'final-audit.json',audit)
 lines=['# Random 5,000 artworks — museum matching at the approved 80% threshold','','Completed '+audit['at']+'. Production assignments and a fresh final database audit are recorded below.','',f"**{len(applied):,} museum connections added in production**, across {audit['distinct_assigned_museums']:,} museums. {len(newinstitutions):,} new museum authorities remain in review. Existing artwork publication states, dates, creator labels/relationships and images were preserved.",'','| Result | Fresh random 5,000 | Earlier 489 leads |','|---|---:|---:|']
 for outcome in sorted({k for c in counts.values()for k in c}):lines.append('| '+outcome.replace('_',' ')+' | '+str(counts['new-5000'].get(outcome,0))+' | '+str(counts['prior-489-leads'].get(outcome,0))+' |')
 lines+=['','## Sampling and research','',f"A fresh sample of 5,000 was drawn without weighting from {sample['eligible_population']:,} eligible production artworks, excluding all 10,000 artworks in the previous two samples. The random seed, complete UUID frame, query plan and baseline are preserved. The 489 still-unresolved original leads were added as a separate follow-up cohort.",'',f"All 5,000 new records received research: {len(initial['new_sample_exact_source_ids']):,} initial exact-source reviews and {len(queried&set(newids)):,} individual follow-up searches. All 489 older leads also received a new individual search. Exact cached WikiArt and Wikidata object captures, verified creator authorities, official museum catalogues, French and Italian object data and indexed primary sources are preserved with retrieval times and hashes.",'','## Decisions','', 'The assistant made the matching decisions at the user-approved minimum 80% editorial confidence. Confidence is an assessment of the evidence, not a calibrated probability. Source object identity, creator and version checks remain mandatory; each accepted claim records its evidence and limitations.','', 'Museum services were verified against official collection pages. Their collection administration is retained without guessing a specific venue or current display. The Atkinson historical gallery/library identity was reconciled to its current museum collection; a library label alone was not used as a reason to reject that art gallery. Other libraries, private collections and government bodies remain explicitly distinguished from museums.','', 'Mixed WikiArt locations were examined individually. The Velázquez Emmaus painting matches the Irish version by title and dimensions; the James Ward mill is documented by the National Library of Wales. The Canaletto page lacks enough version evidence to choose between two museums. Duplicate source objects and shared inventories were checked before delivery.','', 'Unassigned outcomes document non-museum collections, private/unknown whereabouts, insufficient object/version evidence or duplicate catalogue identities. No manual verification is requested from the user.','', '## Production verification','',f"{len(applied):,} museum links were applied and verified across {audit['distinct_assigned_museums']:,} museums. {len(concurrent):,} assignments by concurrent catalogue work were observed separately and excluded from this pass’s write count. Twenty-one offline regression checks passed. Each applied artwork has a sourced accepted holding and citation; artwork metadata, creator relationships, dates, images and publication status were verified unchanged. No current-display claims were added.",'','Recovery backup '+str(audit['backup']['id'])+' completed successfully. Pinned preimages are under `~/Library/Application Support/Artline/backups/random-5000-museums-round3-20261007/`. The local catalogue was not written. No artworks were ingested, images downloaded, commits made or deployment performed.','', 'Source access failures and unresolved qualifications remain in the evidence. Queries were scoped to the sampled IDs and selected institutions. Sampling necessarily enumerated eligible UUIDs; details used bounded batches. The institution/accession check used the indexed bitmap path. The broader holding/source-URL audit used a parallel sequential scan; an indexed URL lookup and representative load testing remain necessary before routine use at ten-million-record scale.','', '## Per-artwork results','', '- [Fresh 5,000 decisions](new-5000-results.md) and [machine-readable ledger](new-5000-results.json.gz).','- [489 original unresolved leads](prior-489-leads-results.md) and [machine-readable ledger](prior-489-leads-results.json.gz).','- [Final database audit](final-audit.json).','- Pinned plans and verification receipts are in `delivery/`; exact source captures and reviews are retained alongside this report.']
 (RUN/'README.md').write_text('\n'.join(lines)+'\n');print(json.dumps({k:audit[k]for k in ['museum_assignments_applied','applied_new_sample','applied_previous_leads','concurrent_assignments_observed','new_review_institutions','distinct_assigned_museums','outcomes','errors']},ensure_ascii=False),flush=True)
